    public class MEInteractingMedicinesController : BaseBusinessController
    {
        public MEInteractingMedicinesController()
        {
            dal = new DALBaseProvider("MEInteractingMedicines", typeof(MEInteractingMedicinesInfo));
        }

        /// <summary>
        /// Get the interacting medicine list of a given medicine
        /// </summary>
        /// <param name="productID">ID of a given medicine</param>
        /// <returns>List of interacting medicines</returns>
        public List<MEInteractingMedicinesInfo> GetInteractingMedicinesByProductID(int productID)
        {
            DataSet ds = dal.GetDataSet("MEInteractingMedicines_GetInteractingMedicinesByProductID", productID);
            List<MEInteractingMedicinesInfo> interactingMedicineList = new List<MEInteractingMedicinesInfo>();
            if (ds.Tables.Count > 0)
            {
                foreach (DataRow row in ds.Tables[0].Rows)
                {
                    MEInteractingMedicinesInfo objInteractingMedicinesInfo = (MEInteractingMedicinesInfo)GetObjectFromDataRow(row);
                    interactingMedicineList.Add(objInteractingMedicinesInfo);
                }
            }
            return interactingMedicineList;
        }
    }
    #endregion
